"""The courtyard: people/semyonych.tsv, nina.tsv, asya.tsv, gosha.tsv, pryanik.tsv.

The main story of the game lives here. Year 1: the hens, the first beds, Nina's house since 1968,
Asya's matchboxes, Gosha's night cello. Year 2: hives on the roof (semyonych.hives), the balcony,
Gosha speaks to Lilya (gosha.lilya), Asya's prize (asya.prize), Nina's granddaughter Dasha (nina.dasha).
Year 3: the shared garden, the seed library (asya.library), the district festival in the player's
honour (semyonych.festival), and then life going on.
"""
from common import write

COLS = "t n gap months when hearts needs reward text_ru text_en reply_ru reply_en sets".split()


def build(lines, reqs, notes):
    rows = []
    for when, ru, en in lines:
        rows.append({"t": "line", "when": when, "text_ru": ru, "text_en": en})
    for i, r in enumerate(reqs, 1):
        gap, months, when, hearts, needs, reward, ru, en, rru, ren = r[:10]
        sets = r[10] if len(r) > 10 else ""
        rows.append({"t": "req", "n": i, "gap": gap, "months": months, "when": when, "hearts": hearts,
                     "needs": needs, "reward": reward, "text_ru": ru, "text_en": en,
                     "reply_ru": rru, "reply_en": ren, "sets": sets})
    for i, r in enumerate(notes, 1):
        gap, months, when, hearts, needs, reward, ru, en = r[:8]
        sets = r[8] if len(r) > 8 else ""
        rows.append({"t": "note", "n": i, "gap": gap, "months": months, "when": when, "hearts": hearts,
                     "needs": needs, "reward": reward, "text_ru": ru, "text_en": en, "sets": sets})
    return rows


